WITH flattened AS (SELECT id, service, log_ts, level, key, v FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, v) SELECT service, COUNT(*) FILTER (WHERE key = 'version') AS version_rows, SIZE(COLLECT_SET(service)) AS num_services, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min_2 FROM flattened GROUP BY 1;
